sap.ui.define([                                                                                                                                                                                                                                                
  "sap/ui/core/mvc/Controller",                                                                                                                                                                                                                                
  "sap/m/MessageToast",                                                                                                                                                                                                                                        
  "sap/m/Dialog",                                                                                                                                                                                                                                              
  "sap/m/Input",                                                                                                                                                                                                                                               
  "sap/m/Label",                                                                                                                                                                                                                                               
  "sap/m/Text",                                                                                                                                                                                                                                                
  "sap/m/Button"                                                                                                                                                                                                                                               
], function (Controller, MessageToast, Dialog, Input, Label, Text, Button) {                                                                                                                                                                                   
  "use strict";                                                                                                                                                                                                                                                
  var API = "/sap/bc/zbpc_git/";                                                                                                                                                                                                                               
  var ENVIRONMENT_KEY = "bpcGit.environment";                                                                                                                                                                                                                  
  // Text and colour of each workbook status (docs/SPEC.md section 4, F3).                                                                                                                                                                                     
  var STATUS = {                                                                                                                                                                                                                                               
    UNCHANGED: { text: "Unchanged", state: "Success" },                                                                                                                                                                                                        
    MODIFIED_BPC: { text: "Modified in BPC", state: "Warning" },                                                                                                                                                                                               
    MODIFIED_GIT: { text: "Modified in Git", state: "Warning" },                                                                                                                                                                                               
    CONFLICT: { text: "Conflict", state: "Error" },                                                                                                                                                                                                            
    NEW_BPC: { text: "New in BPC", state: "None" },                                                                                                                                                                                                            
    NEW_GIT: { text: "New in Git", state: "None" },                                                                                                                                                                                                            
    DELETED_BPC: { text: "Deleted in BPC", state: "Error" },                                                                                                                                                                                                   
    DELETED_GIT: { text: "Deleted in Git", state: "Warning" },                                                                                                                                                                                                 
    DIFFERS: { text: "Differs, never synced", state: "Warning" }                                                                                                                                                                                               
  };                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                               
  return Controller.extend("bpc.git.controller.App", {                                                                                                                                                                                                         
    onInit: function () {                                                                                                                                                                                                                                      
      this._model = this.getOwnerComponent().getModel("app");                                                                                                                                                                                                  
      // Git login, as in abapGit: asked only when the Git host wants it, kept                                                                                                                                                                                 
      // in this page's memory only (never stored), gone when the page reloads.                                                                                                                                                                                
      this._credentials = null;                                                                                                                                                                                                                                
      this.onPing();                                                                                                                                                                                                                                           
      this._loadEnvironments();                                                                                                                                                                                                                                
    },                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    // Checks that the bpcGit API answers and that abapGit is installed.                                                                                                                                                                                       
    onPing: function () {                                                                                                                                                                                                                                      
      var oModel = this._model;                                                                                                                                                                                                                                
      oModel.setProperty("/pingBusy", true);                                                                                                                                                                                                                   
      this._request("ping").then(function (oData) {                                                                                                                                                                                                            
        oModel.setProperty("/ping", oData);                                                                                                                                                                                                                    
        oModel.setProperty("/pingError", "");                                                                                                                                                                                                                  
      }, function (oError) {                                                                                                                                                                                                                                   
        oModel.setProperty("/ping", null);                                                                                                                                                                                                                     
        oModel.setProperty("/pingError", oError.message);                                                                                                                                                                                                      
      }).then(function () {                                                                                                                                                                                                                                    
        oModel.setProperty("/pingBusy", false);                                                                                                                                                                                                                
      });                                                                                                                                                                                                                                                      
    },                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    onEnvironmentChange: function () {                                                                                                                                                                                                                         
      var sEnvironment = this._model.getProperty("/environment");                                                                                                                                                                                              
      try { window.localStorage.setItem(ENVIRONMENT_KEY, sEnvironment); } catch (e) { /* storage unavailable */ }                                                                                                                                              
      this._loadConfig(sEnvironment);                                                                                                                                                                                                                          
    },                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    onSave: function () {                                                                                                                                                                                                                                      
      var oModel = this._model;                                                                                                                                                                                                                                
      var oConfig = oModel.getProperty("/config");                                                                                                                                                                                                             
      oModel.setProperty("/setupBusy", true);                                                                                                                                                                                                                  
      oModel.setProperty("/setupError", "");                                                                                                                                                                                                                   
      this._request("config", {                                                                                                                                                                                                                                
        environment: oModel.getProperty("/environment"),                                                                                                                                                                                                       
        url: oConfig.url,                                                                                                                                                                                                                                      
        branch: oConfig.branch                                                                                                                                                                                                                                 
      }, "POST").then(function (oData) {                                                                                                                                                                                                                       
        this._showConfig(oData);                                                                                                                                                                                                                               
        MessageToast.show("Repository setup saved");                                                                                                                                                                                                           
      }.bind(this), this._setupFailed.bind(this));                                                                                                                                                                                                             
    },                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    // Reads the branches; with a login, also checks push access.                                                                                                                                                                                              
    onTestConnection: function () {                                                                                                                                                                                                                            
      this._testConnection();                                                                                                                                                                                                                                  
    },                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    // Asks for the login first, so push access is checked too.                                                                                                                                                                                                
    onLogin: function () {                                                                                                                                                                                                                                     
      this._askCredentials("Log in to check that you may push to the repository.").then(function (oCredentials) {                                                                                                                                              
        this._setCredentials(oCredentials);                                                                                                                                                                                                                    
        this._testConnection();                                                                                                                                                                                                                                
      }.bind(this), function () { /* cancelled */ });                                                                                                                                                                                                          
    },                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    onLogout: function () {                                                                                                                                                                                                                                    
      this._setCredentials(null);                                                                                                                                                                                                                              
      this._model.setProperty("/connection", null);                                                                                                                                                                                                            
      MessageToast.show("Git login removed from this page");                                                                                                                                                                                                   
    },                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    onRefreshWorkbooks: function () {                                                                                                                                                                                                                          
      this._loadWorkbooks();                                                                                                                                                                                                                                   
    },                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    onFilterChange: function () {                                                                                                                                                                                                                              
      this._applyFilter();                                                                                                                                                                                                                                     
    },                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    _testConnection: function () {                                                                                                                                                                                                                             
      var oModel = this._model;                                                                                                                                                                                                                                
      oModel.setProperty("/connectionBusy", true);                                                                                                                                                                                                             
      oModel.setProperty("/connectionError", "");                                                                                                                                                                                                              
      this._gitRequest("connection", { environment: oModel.getProperty("/environment") }).then(function (oData) {                                                                                                                                              
        oData.branchesText = oData.branches.join(", ");                                                                                                                                                                                                        
        oModel.setProperty("/connection", oData);                                                                                                                                                                                                              
      }, function (oError) {                                                                                                                                                                                                                                   
        oModel.setProperty("/connection", null);                                                                                                                                                                                                               
        if (!oError.cancelled) {                                                                                                                                                                                                                               
          oModel.setProperty("/connectionError", oError.message);                                                                                                                                                                                              
        }                                                                                                                                                                                                                                                      
      }).then(function () {                                                                                                                                                                                                                                    
        oModel.setProperty("/connectionBusy", false);                                                                                                                                                                                                          
      });                                                                                                                                                                                                                                                      
    },                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    _loadWorkbooks: function () {                                                                                                                                                                                                                              
      var oModel = this._model;                                                                                                                                                                                                                                
      oModel.setProperty("/workbooksBusy", true);                                                                                                                                                                                                              
      oModel.setProperty("/workbooksError", "");                                                                                                                                                                                                               
      this._gitRequest("workbooks", { environment: oModel.getProperty("/environment") }).then(function (oData) {                                                                                                                                               
        oModel.setProperty("/overview", {                                                                                                                                                                                                                      
          text: oData.branchFound ? "Branch " + oData.branch + " at commit " + oData.commit.substring(0, 7) :                                                                                                                                                  
            "Branch " + oData.branch + " does not exist yet, so every workbook is new in BPC"                                                                                                                                                                  
        });                                                                                                                                                                                                                                                    
        oModel.setProperty("/workbooks", oData.workbooks.map(this._toRow));                                                                                                                                                                                    
        this._applyFilter();                                                                                                                                                                                                                                   
      }.bind(this), function (oError) {                                                                                                                                                                                                                        
        oModel.setProperty("/overview", null);                                                                                                                                                                                                                 
        oModel.setProperty("/workbooks", []);                                                                                                                                                                                                                  
        this._applyFilter();                                                                                                                                                                                                                                   
        oModel.setProperty("/workbooksError", oError.cancelled ?                                                                                                                                                                                               
          "Log in to see the workbooks of this repository." : oError.message);                                                                                                                                                                                 
      }.bind(this)).then(function () {                                                                                                                                                                                                                         
        oModel.setProperty("/workbooksBusy", false);                                                                                                                                                                                                           
      });                                                                                                                                                                                                                                                      
    },                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    // Adds the display fields of one workbook from the API.                                                                                                                                                                                                   
    _toRow: function (oWorkbook) {                                                                                                                                                                                                                             
      var aParts = oWorkbook.path.split("/");                                                                                                                                                                                                                  
      var oStatus = STATUS[oWorkbook.status] || { text: oWorkbook.status, state: "None" };                                                                                                                                                                     
      return jQuery.extend({}, oWorkbook, {                                                                                                                                                                                                                    
        name: aParts[aParts.length - 1],                                                                                                                                                                                                                       
        folder: aParts.slice(1, -1).join("/"),                                                                                                                                                                                                                 
        statusText: oStatus.text,                                                                                                                                                                                                                              
        statusState: oStatus.state,                                                                                                                                                                                                                            
        changedText: oWorkbook.inBpc ? oWorkbook.changedAt + " by " + oWorkbook.changedBy : "",                                                                                                                                                                
        sizeText: oWorkbook.inBpc ? Math.max(1, Math.round(oWorkbook.size / 1024)) + " KB" : "",                                                                                                                                                               
        // BPC keeps old versions in BACKUP folders and as "COPY OF ..." files                                                                                                                                                                                 
        isBackup: /\/BACKUP\//.test(oWorkbook.path) || /^COPY OF /.test(aParts[aParts.length - 1])                                                                                                                                                             
      });                                                                                                                                                                                                                                                      
    },                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    _applyFilter: function () {                                                                                                                                                                                                                                
      var oModel = this._model;                                                                                                                                                                                                                                
      var oFilter = oModel.getProperty("/filter");                                                                                                                                                                                                             
      var sSearch = (oFilter.search || "").toUpperCase();                                                                                                                                                                                                      
      var aAll = oModel.getProperty("/workbooks");                                                                                                                                                                                                             
      var aShown = aAll.filter(function (oRow) {                                                                                                                                                                                                               
        if (oFilter.hideBackups && oRow.isBackup) { return false; }                                                                                                                                                                                            
        if (oFilter.status === "CHANGED" && oRow.status === "UNCHANGED") { return false; }                                                                                                                                                                     
        if (oFilter.status !== "ALL" && oFilter.status !== "CHANGED" && oRow.status !== oFilter.status) { return false; }                                                                                                                                      
        return !sSearch || oRow.path.toUpperCase().indexOf(sSearch) >= 0;                                                                                                                                                                                      
      });                                                                                                                                                                                                                                                      
      var mCounts = {};                                                                                                                                                                                                                                        
      aAll.forEach(function (oRow) {                                                                                                                                                                                                                           
        if (!(oFilter.hideBackups && oRow.isBackup)) {                                                                                                                                                                                                         
          mCounts[oRow.statusText] = (mCounts[oRow.statusText] || 0) + 1;                                                                                                                                                                                      
        }                                                                                                                                                                                                                                                      
      });                                                                                                                                                                                                                                                      
      oModel.setProperty("/workbooksView", aShown);                                                                                                                                                                                                            
      oModel.setProperty("/workbooksTitle", "Workbooks (" + aShown.length +                                                                                                                                                                                    
        (aShown.length === aAll.length ? ")" : " of " + aAll.length + ")"));                                                                                                                                                                                   
      oModel.setProperty("/workbooksSummary", Object.keys(mCounts).sort().map(function (sText) {                                                                                                                                                               
        return mCounts[sText] + " " + sText.toLowerCase();                                                                                                                                                                                                     
      }).join(", "));                                                                                                                                                                                                                                          
    },                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    // POST to a resource that talks to the Git host. Sends the login if there                                                                                                                                                                                 
    // is one; when the host wants one (or rejects it), asks for it and retries.                                                                                                                                                                               
    _gitRequest: function (sResource, mParams) {                                                                                                                                                                                                               
      var mData = jQuery.extend({}, mParams);                                                                                                                                                                                                                  
      if (this._credentials) {                                                                                                                                                                                                                                 
        mData.user = this._credentials.user;                                                                                                                                                                                                                   
        mData.token = this._credentials.token;                                                                                                                                                                                                                 
      }                                                                                                                                                                                                                                                        
      return this._request(sResource, mData, "POST").catch(function (oError) {                                                                                                                                                                                 
        if (!oError.authRequired) {                                                                                                                                                                                                                            
          throw oError;                                                                                                                                                                                                                                        
        }                                                                                                                                                                                                                                                      
        return this._askCredentials(oError.message).then(function (oCredentials) {                                                                                                                                                                             
          this._setCredentials(oCredentials);                                                                                                                                                                                                                  
          return this._gitRequest(sResource, mParams);                                                                                                                                                                                                         
        }.bind(this));                                                                                                                                                                                                                                         
      }.bind(this));                                                                                                                                                                                                                                           
    },                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    _setCredentials: function (oCredentials) {                                                                                                                                                                                                                 
      this._credentials = oCredentials;                                                                                                                                                                                                                        
      this._model.setProperty("/gitUser", oCredentials ? oCredentials.user : "");                                                                                                                                                                              
    },                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    // Login dialog; resolves with { user, token }, rejects with a cancelled Error.                                                                                                                                                                            
    _askCredentials: function (sMessage) {                                                                                                                                                                                                                     
      return new Promise(function (resolve, reject) {                                                                                                                                                                                                          
        var bLoggedIn = false;                                                                                                                                                                                                                                 
        var oUser = new Input({ value: this._model.getProperty("/gitUser"), placeholder: "User name" });                                                                                                                                                       
        var oToken = new Input({ type: "Password", placeholder: "Personal access token" });                                                                                                                                                                    
        var oDialog = new Dialog({                                                                                                                                                                                                                             
          title: "Git login",                                                                                                                                                                                                                                  
          contentWidth: "24rem",                                                                                                                                                                                                                               
          content: [                                                                                                                                                                                                                                           
            new Text({ text: sMessage }).addStyleClass("sapUiSmallMarginBottom"),                                                                                                                                                                              
            new Label({ text: "User", labelFor: oUser, required: true }),                                                                                                                                                                                      
            oUser,                                                                                                                                                                                                                                             
            new Label({ text: "Access token", labelFor: oToken, required: true }),                                                                                                                                                                             
            oToken,                                                                                                                                                                                                                                            
            new Text({ text: "GitHub needs a personal access token, not your password. " +                                                                                                                                                                     
              "It is kept in this page only and is gone when you reload it." }).addStyleClass("sapUiSmallMarginTop")                                                                                                                                           
          ],                                                                                                                                                                                                                                                   
          beginButton: new Button({                                                                                                                                                                                                                            
            text: "Log in",                                                                                                                                                                                                                                    
            type: "Emphasized",                                                                                                                                                                                                                                
            press: function () {                                                                                                                                                                                                                               
              var sUser = oUser.getValue().trim();                                                                                                                                                                                                             
              var sToken = oToken.getValue().trim();                                                                                                                                                                                                           
              oUser.setValueState(sUser ? "None" : "Error");                                                                                                                                                                                                   
              oToken.setValueState(sToken ? "None" : "Error");                                                                                                                                                                                                 
              if (sUser && sToken) {                                                                                                                                                                                                                           
                bLoggedIn = true;                                                                                                                                                                                                                              
                oDialog.close();                                                                                                                                                                                                                               
                resolve({ user: sUser, token: sToken });                                                                                                                                                                                                       
              }                                                                                                                                                                                                                                                
            }                                                                                                                                                                                                                                                  
          }),                                                                                                                                                                                                                                                  
          endButton: new Button({ text: "Cancel", press: function () { oDialog.close(); } }),                                                                                                                                                                  
          afterClose: function () {                                                                                                                                                                                                                            
            oDialog.destroy();                                                                                                                                                                                                                                 
            if (!bLoggedIn) {                                                                                                                                                                                                                                  
              var oError = new Error("Login cancelled");                                                                                                                                                                                                       
              oError.cancelled = true;                                                                                                                                                                                                                         
              reject(oError);                                                                                                                                                                                                                                  
            }                                                                                                                                                                                                                                                  
          }                                                                                                                                                                                                                                                    
        }).addStyleClass("sapUiContentPadding");                                                                                                                                                                                                               
        this.getView().addDependent(oDialog);                                                                                                                                                                                                                  
        oDialog.open();                                                                                                                                                                                                                                        
      }.bind(this));                                                                                                                                                                                                                                           
    },                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    _loadEnvironments: function () {                                                                                                                                                                                                                           
      var oModel = this._model;                                                                                                                                                                                                                                
      oModel.setProperty("/setupBusy", true);                                                                                                                                                                                                                  
      this._request("environments").then(function (oData) {                                                                                                                                                                                                    
        var aEnvironments = oData.environments;                                                                                                                                                                                                                
        var sSaved = "";                                                                                                                                                                                                                                       
        oModel.setProperty("/environments", aEnvironments);                                                                                                                                                                                                    
        try { sSaved = window.localStorage.getItem(ENVIRONMENT_KEY) || ""; } catch (e) { /* storage unavailable */ }                                                                                                                                           
        var bSavedValid = aEnvironments.some(function (oItem) { return oItem.id === sSaved; });                                                                                                                                                                
        var sEnvironment = bSavedValid ? sSaved : (aEnvironments.length ? aEnvironments[0].id : "");                                                                                                                                                           
        oModel.setProperty("/environment", sEnvironment);                                                                                                                                                                                                      
        if (sEnvironment) {                                                                                                                                                                                                                                    
          this._loadConfig(sEnvironment);                                                                                                                                                                                                                      
        } else {                                                                                                                                                                                                                                               
          oModel.setProperty("/setupBusy", false);                                                                                                                                                                                                             
          oModel.setProperty("/setupError", "You have no access to any BPC environment.");                                                                                                                                                                     
        }                                                                                                                                                                                                                                                      
      }.bind(this), this._setupFailed.bind(this));                                                                                                                                                                                                             
    },                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    _loadConfig: function (sEnvironment) {                                                                                                                                                                                                                     
      var oModel = this._model;                                                                                                                                                                                                                                
      oModel.setProperty("/setupBusy", true);                                                                                                                                                                                                                  
      oModel.setProperty("/setupError", "");                                                                                                                                                                                                                   
      oModel.setProperty("/connection", null);                                                                                                                                                                                                                 
      oModel.setProperty("/connectionError", "");                                                                                                                                                                                                              
      oModel.setProperty("/overview", null);                                                                                                                                                                                                                   
      oModel.setProperty("/workbooks", []);                                                                                                                                                                                                                    
      oModel.setProperty("/workbooksError", "");                                                                                                                                                                                                               
      this._applyFilter();                                                                                                                                                                                                                                     
      this._request("config", { environment: sEnvironment }).then(function (oData) {                                                                                                                                                                           
        this._showConfig(oData);                                                                                                                                                                                                                               
        if (oData.configured) {                                                                                                                                                                                                                                
          this._loadWorkbooks();                                                                                                                                                                                                                               
        }                                                                                                                                                                                                                                                      
      }.bind(this), this._setupFailed.bind(this));                                                                                                                                                                                                             
    },                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    _showConfig: function (oData) {                                                                                                                                                                                                                            
      var oModel = this._model;                                                                                                                                                                                                                                
      oModel.setProperty("/config", {                                                                                                                                                                                                                          
        url: oData.url,                                                                                                                                                                                                                                        
        branch: oData.branch || "main"                                                                                                                                                                                                                         
      });                                                                                                                                                                                                                                                      
      oModel.setProperty("/configured", oData.configured);                                                                                                                                                                                                     
      oModel.setProperty("/changedText", oData.configured ?                                                                                                                                                                                                    
        "Last saved by " + oData.changedBy + " on " + oData.changedAt : "Not set up yet");                                                                                                                                                                     
      oModel.setProperty("/setupBusy", false);                                                                                                                                                                                                                 
    },                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    _setupFailed: function (oError) {                                                                                                                                                                                                                          
      this._model.setProperty("/setupBusy", false);                                                                                                                                                                                                            
      this._model.setProperty("/setupError", oError.message);                                                                                                                                                                                                  
    },                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    // GET or POST to the bpcGit API; resolves with the JSON body, rejects with                                                                                                                                                                                
    // an Error that carries authRequired when the Git host wants a login.                                                                                                                                                                                     
    _request: function (sResource, mParams, sMethod) {                                                                                                                                                                                                         
      var sClient = jQuery.sap.getUriParameters().get("sap-client");                                                                                                                                                                                           
      var sUrl = API + sResource;                                                                                                                                                                                                                              
      if (sClient) {                                                                                                                                                                                                                                           
        sUrl += "?sap-client=" + encodeURIComponent(sClient);                                                                                                                                                                                                  
      }                                                                                                                                                                                                                                                        
      return new Promise(function (resolve, reject) {                                                                                                                                                                                                          
        jQuery.ajax({ url: sUrl, type: sMethod || "GET", dataType: "json", data: mParams || {},                                                                                                                                                                
          cache: false, timeout: 300000,                                                                                                                                                                                                                       
          success: resolve,                                                                                                                                                                                                                                    
          error: function (oXHR) {                                                                                                                                                                                                                             
            var oBody = oXHR.responseJSON;                                                                                                                                                                                                                     
            var oError = new Error(oBody && oBody.error ? oBody.error.message :                                                                                                                                                                                
              "Cannot load " + sResource + " (" + oXHR.status + " " + oXHR.statusText + ")");                                                                                                                                                                  
            oError.authRequired = !!(oBody && oBody.error && oBody.error.authRequired);                                                                                                                                                                        
            reject(oError);                                                                                                                                                                                                                                    
          }                                                                                                                                                                                                                                                    
        });                                                                                                                                                                                                                                                    
      });                                                                                                                                                                                                                                                      
    }                                                                                                                                                                                                                                                          
  });                                                                                                                                                                                                                                                          
});                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                               